+import { uploadOne, uploadAll } from "../src/upload";
+import { postFile } from "../src/api";
+
+jest.mock("../src/api");
+jest.mock("../src/toast");
+
+test("retries a failed upload up to 3 times before giving up", async () => {
+  (postFile as jest.Mock).mockRejectedValue(new Error("net"));
+  await expect(uploadOne(fakeFile())).rejects.toThrow("net");
+  expect(postFile).toHaveBeenCalledTimes(3);
+});
+
+test("uploadAll rejects when an upload permanently fails", async () => {
+  (postFile as jest.Mock).mockRejectedValue(new Error("net"));
+  await expect(uploadAll([fakeFile()])).rejects.toThrow();
+});
+
+declare function fakeFile(): File;
